def compute_r(q):
    # TE's initialization hook holds the first leaf, not an empty state.
    def identity_r(t0, t1):
        return (
            S[0, q],  # mx_col
            tir.const(1.0, "float32"),  # den_col
        )
    fused_r = te.comm_reducer(merge_r, identity_r, name="fused_r")
    return fused_r(
        (
            S[r, q],  # mx_col
            tir.const(1.0, "float32"),  # den_col
        ),
        axis=r,
    )

mx_col, den_col = te.compute(
    (n,), compute_r,
    name="fused_mx_col_den_col",
    tag="superopt.nonempty",
)
mx_col, den_col = te.compute(
    (n,),
    lambda q: (
        tir.if_then_else(n == 1, S[0, q], mx_col[q]),
        tir.if_then_else(n == 1, tir.const(1.0, "float32"), den_col[q]),
    ),
    name="nonempty_fused_mx_col_den_col", tag="superopt.singleton",
)
